int main() {
    string input_str, output_str;
    bool inserted_at_flag = false;
    cin >> input_str;
    size_t idx = 0;
    while (idx < input_str.size()) {
        if (input_str.compare(idx, 3, "dot") == 0) {
            output_str += '.';
            idx += 3;
        } else if (input_str.compare(idx, 2, "at") == 0 && !inserted_at_flag && idx != 0) {
