            ++idx;
        }
    }
    for (size_t j = 0; j < output_str.size(); ++j) {
        if (j == 0 && output_str[j] == '.') cout << "dot";
        else if (j == 0 && output_str[j] == '@') cout << "at";
        else if (j == output_str.size() - 1 && output_str.back() == '@') cout << "at";
        else if (j == output_str.size() - 1 && output_str.back() == '.') cout << "dot";
        else cout << output_str[j];
    }
    cout << endl;
    return 0;
}
